import re, json
with open('/tmp/commits.html') as f:
    content = f.read()

# Find all script tags with type application/json
scripts = re.findall(r'<script type=\"application/json\"[^>]*>(.*?)</script>', content, re.DOTALL)
for i, script in enumerate(scripts):
    try:
        data = json.loads(script)
        if isinstance(data, dict) and 'payload' in data:
            payload = data['payload']
            if isinstance(payload, dict):
                print(f'Block {i} payload keys:', list(payload.keys())[:20])
                if 'commitGroups' in payload:
                    print('Found commitGroups!')
                    for group in payload['commitGroups'][:1]:
                        if 'commits' in group and group['commits']:
                            print('First commit:', group['commits'][0].get('committedDate', 'no date'))
                if 'tree' in payload:
                    print('Found tree')
    except Exception as e:
        pass
"

