for i, script in enumerate(scripts):
    try:
        data = json.loads(script)
        if isinstance(data, dict):
            if 'payload' in data and isinstance(data['payload'], dict):
                if 'preloaded_records' in data['payload']:
                    preloaded = data['payload']['preloaded_records']
                    if isinstance(preloaded, dict):
                        # Look for issue data in preloaded records
                        for key, value in preloaded.items():
                            if isinstance(value, dict) and ('issueCount' in value or 'openCount' in value):
                                print(f'Key {key}:', value)
                            if isinstance(value, list):
                                print(f'Key {key} is list of length {len(value)}')
                                if len(value) > 0 and isinstance(value[0], dict):
                                    print('First item keys:', list(value[0].keys())[:20])
                                    if 'isPullRequest' in value[0]:
                                        open_issues = [x for x in value if not x.get('isPullRequest', False)]
                                        print(f'Open issues (not PRs): {len(open_issues)}')
                                        print(f'Total items: {len(value)}')
                    break
    except Exception as e:
        print(f'Error in block {i}:', e)
"

