import re, json
with open('/tmp/issues_only.html') as f:
    content = f.read()

scripts = re.findall(r'<script type=\"application/json\"[^>]*>(.*?)</script>', content, re.DOTALL)
for i, script in enumerate(scripts):
    try:
        data = json.loads(script)
        if isinstance(data, dict) and 'payload' in data:
            payload = data['payload']
            if isinstance(payload, dict) and 'preloaded_records' in payload:
                preloaded = payload['preloaded_records']
                for key, value in preloaded.items():
                    if isinstance(value, list):
                        pr_count = 0
                        issue_count = 0
                        for item in value:
                            if isinstance(item, dict):
                                if item.get('isPullRequest', False) or item.get('pull_request') or 'pullRequest' in item:
                                    pr_count += 1
                                else:
                                    issue_count += 1
                        print(f'Key {key}: total={len(value)}, PRs={pr_count}, issues={issue_count}')
                        if len(value) > 0:
                            print('First item keys:', list(value[0].keys())[:20])
    except Exception as e:
        print(f'Error: {e}')
"

